package com.college.hospitalmanagement;
import com.college.hospitalmanagement.dto.*;import jakarta.validation.Valid;import java.net.URI;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/patients") public class PatientController{private final PatientService service;public PatientController(PatientService service){this.service=service;}@PostMapping public ResponseEntity<PatientResponseDTO> create(@Valid @RequestBody PatientRequestDTO r){PatientResponseDTO p=service.create(r);return ResponseEntity.created(URI.create("/api/patients/"+p.id())).body(p);}@GetMapping public List<PatientResponseDTO> list(){return service.list();}@GetMapping("/{id}") public PatientResponseDTO get(@PathVariable Long id){return service.get(id);}@PutMapping("/{id}") public PatientResponseDTO update(@PathVariable Long id,@Valid @RequestBody PatientRequestDTO r){return service.update(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
